INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:cognitive load','cognitive load','n','فشار ذهنی','≈ mental effort — Cambridge 10 · Test 1 · Passage 3: The Psychology of Memory | Cambridge 19 · Test 3 · Passage 2: Neuroscience & Brain Connectivity','Too much information increases cognitive load.','[["Too much information increases cognitive load.","اطلاعات بیش از حد، بار شناختی را افزایش می‌دهد."],["Excessive cognitive load reduces accuracy.","بار شناختی بیش از حد باعث کاهش دقت می‌شود."]]','cambridge',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
