INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:infrastructure','infrastructure','n','زیرساخت','≈ framework, foundation — Cambridge 10 · Test 2 · Passage 1: European Transport Systems | Cambridge 11 · Test 2 · Passage 1: Irrigation in Ancient Civilisations | Cambridge 12 · Test 4 · Passage 1: Urban Development & City Design','Cities must invest in sustainable transport infrastructure.','[["Cities must invest in sustainable transport infrastructure.","شهرها باید در زیرساخت‌های حمل و نقل پایدار سرمایه گذاری کنند."],["The irrigation infrastructure supported the empire''s economy.","زیرساخت‌های آبیاری از اقتصاد امپراتوری حمایت می‌کرد."],["Urban infrastructure must evolve to support population growth.","زیرساخت‌های شهری باید برای حمایت از رشد جمعیت توسعه یابد."],["Reliable infrastructure supports tourism.","زیرساخت‌های قابل اعتماد از گردشگری حمایت می‌کند."]]','cambridge',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
