INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:commuter','commuter','n','فردی که روزانه رفت‌و‌آمد می‌کند','≈ traveller, passenger — Cambridge 10 · Test 2 · Passage 1: European Transport Systems | Cambridge 12 · Test 4 · Passage 1: Urban Development & City Design','Millions of commuters rely on public transport.','[["Millions of commuters rely on public transport.","میلیون‌ها مسافر به حمل و نقل عمومی متکی هستند."],["Thousands of commuters use the metro every morning.","هزاران مسافر هر روز صبح از مترو استفاده می‌کنند."]]','cambridge',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
