INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:efficiency','efficiency','n','کارایی','≈ effectiveness, productivity — Cambridge 10 · Test 2 · Passage 1: European Transport Systems | Cambridge 11 · Test 4 · Passage 1: Renewable Energy Resources | Cambridge 12 · Test 2 · Passage 1: The Intelligence of Ants','Better traffic management improves transport efficiency.','[["Better traffic management improves transport efficiency.","مدیریت ترافیک بهتر کارایی حمل و نقل را بهبود می‌بخشد."],["Efficiency improvements lower production costs.","بهبود بهره وری هزینه‌های تولید را کاهش می‌دهد."],["The efficiency of ants is unmatched in nature.","کارایی مورچه‌ها در طبیعت بی نظیر است."]]','cambridge',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
