INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:curriculum','curriculum','n','برنامه درسی','≈ syllabus, course — Cambridge 10 · Test 2 · Passage 3: Gifted Children and Education | Cambridge 14 · Test 2 · Passage 3: Intelligence & Learning Theories | Cambridge 15 · Test 2 · Passage 1: Education Systems & Learning Models','Schools adapt the curriculum for gifted learners.','[["Schools adapt the curriculum for gifted learners.","مدارس برنامه درسی را برای دانش آموزان با استعداد تطبیق می‌دهند."],["The curriculum incorporates diverse learning styles.","برنامه درسی شامل سبک‌های یادگیری متنوع است."],["The national curriculum emphasizes analytical skills.","برنامه درسی ملی بر مهارت‌های تحلیلی تأکید دارد."]]','cambridge',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
