INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:curator','curator','n','سرپرست موزه یا نمایشگاه','≈ keeper, custodian — Cambridge 10 · Test 3 · Passage 1: The Value of Museums | Cambridge 16 · Test 1 · Passage 2: Art Museums & Public Perception','The curator selected artworks for the new exhibition.','[["The curator selected artworks for the new exhibition.","کیوریتور آثار هنری را برای نمایشگاه جدید انتخاب کرد."],["Curators design exhibitions to educate the public.","متصدیان نمایشگاه‌هایی را برای آموزش عموم طراحی می‌کنند."]]','cambridge',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:artifact','artifact','n','شیء تاریخی / اثر باستانی','≈ object, relic — Cambridge 10 · Test 3 · Passage 1: The Value of Museums | Cambridge 10 · Test 4 · Passage 2: The Lost Civilisations of South America | Cambridge 15 · Test 4 · Passage 1: Cultural Heritage & Historical Conservation','Ancient artifacts reveal details of early civilizations.','[["Ancient artifacts reveal details of early civilizations.","آثار باستانی جزئیات تمدن‌های اولیه را نشان می‌دهد."],["Thousands of artifacts were found in the temple ruins.","هزاران اثر در ویرانه‌های معبد پیدا شد."],["Artifacts provide insights into ancient civilizations.","مصنوعات بینشی در مورد تمدن‌های باستانی ارائه می‌دهند."]]','cambridge',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:authentic','authentic','adj','اصیل، واقعی','≈ genuine, original — Cambridge 10 · Test 3 · Passage 1: The Value of Museums | Cambridge 12 · Test 1 · Passage 2: The Psychology of Collecting','Museums aim to display authentic historical items.','[["Museums aim to display authentic historical items.","هدف موزه‌ها نمایش اقلام تاریخی معتبر است."],["Museums verify that items are authentic.","موزه‌ها اصالت اقلام را تأیید می‌کنند."]]','cambridge',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:restoration','restoration','n','مرمت، بازسازی','≈ repair, renovation — Cambridge 10 · Test 3 · Passage 1: The Value of Museums | Cambridge 11 · Test 3 · Passage 1: The Taj Mahal | Cambridge 15 · Test 4 · Passage 1: Cultural Heritage & Historical Conservation','The restoration of old statues requires delicate work.','[["The restoration of old statues requires delicate work.","مرمت مجسمه‌های قدیمی نیاز به کار ظریفی دارد."],["Ongoing restoration preserves the monument''s beauty.","مرمت مداوم زیبایی این بنا را حفظ می‌کند."],["Restoration projects revive ancient architecture.","پروژه‌های مرمت معماری باستانی را احیا می‌کند."]]','cambridge',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:replica','replica','n','نسخه بازسازی‌شده یا کپی دقیق','≈ copy, reproduction — Cambridge 10 · Test 3 · Passage 1: The Value of Museums','The museum displayed a replica of the lost sculpture.','[["The museum displayed a replica of the lost sculpture.","در این موزه یک ماکت از مجسمه گمشده به نمایش گذاشته شد."]]','cambridge',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:interpretation','interpretation','n','تفسیر، بازنمایی','≈ explanation, presentation — Cambridge 10 · Test 3 · Passage 1: The Value of Museums | Cambridge 14 · Test 4 · Passage 2: Visual Perception & Optical Illusions | Cambridge 15 · Test 3 · Passage 1: Ancient Cave Paintings & Human Expression','Each exhibit offers a different interpretation of history.','[["Each exhibit offers a different interpretation of history.","هر نمایشگاه تفسیر متفاوتی از تاریخ ارائه می‌دهد."],["The mind''s interpretation can differ from reality.","تفسیر ذهن می‌تواند با واقعیت متفاوت باشد."],["The meaning of cave art remains open to interpretation.","معنای هنر غار همچنان قابل تفسیر است."]]','cambridge',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
