INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:magnitude','magnitude','n','بزرگی، شدت','≈ scale, size — Cambridge 10 · Test 3 · Passage 2: The Power of Nature: Volcanic Eruptions','Scientists measured the eruption''s magnitude using modern instruments.','[["Scientists measured the eruption''s magnitude using modern instruments.","دانشمندان بزرگی فوران را با استفاده از ابزارهای مدرن اندازه گیری کردند."]]','cambridge',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
