INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:hazard','hazard','n','خطر طبیعی','≈ risk, danger — Cambridge 10 · Test 3 · Passage 2: The Power of Nature: Volcanic Eruptions | Cambridge 11 · Test 3 · Passage 3: Risk Perception','Volcanic ash poses a hazard to aircraft.','[["Volcanic ash poses a hazard to aircraft.","خاکستر آتشفشانی برای هواپیماها خطرناک است."],["Flooding is a natural hazard in coastal regions.","سیل یک خطر طبیعی در مناطق ساحلی است."]]','cambridge',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
