INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:geothermal','geothermal','adj','زمین‌گرمایی','≈ heat-related, subsurface — Cambridge 10 · Test 3 · Passage 2: The Power of Nature: Volcanic Eruptions | Cambridge 11 · Test 4 · Passage 1: Renewable Energy Resources','Iceland uses geothermal energy from volcanic areas.','[["Iceland uses geothermal energy from volcanic areas.","ایسلند از انرژی زمین گرمایی مناطق آتشفشانی استفاده می‌کند."],["Geothermal power is generated from heat beneath the Earth''s surface.","نیروی زمین گرمایی از گرمای زیر سطح زمین تولید می‌شود."]]','cambridge',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
