INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:hierarchy','hierarchy','n','سلسله‌مراتب','≈ ranking, order — Cambridge 10 · Test 3 · Passage 3: Teamwork and Collaboration | Cambridge 11 · Test 2 · Passage 3: Animal Communication & Language Evolution | Cambridge 12 · Test 2 · Passage 1: The Intelligence of Ants','Traditional hierarchies can slow innovation.','[["Traditional hierarchies can slow innovation.","سلسله مراتب سنتی می‌تواند نوآوری را کند کند."],["Communication strengthens social hierarchies.","ارتباطات سلسله مراتب اجتماعی را تقویت می‌کند."],["The queen sits at the top of the colony hierarchy.","ملکه در بالای سلسله مراتب مستعمره قرار دارد."],["Hierarchies emerge naturally in human groups.","سلسله مراتب به طور طبیعی در گروه‌های انسانی پدیدار می‌شود."]]','cambridge',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
