INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:resilient','resilient','adj','مقاوم، سازگار با سختی','≈ tough, adaptable — Cambridge 10 · Test 4 · Passage 1: The Megafires of California | Cambridge 12 · Test 1 · Passage 1: Cork','Forests can be resilient if managed properly.','[["Forests can be resilient if managed properly.","اگر جنگل‌ها به درستی مدیریت شوند، می‌توانند انعطاف پذیر باشند."],["Its resilient nature prevents cracking.","ماهیت انعطاف پذیر آن از ترک خوردن جلوگیری می‌کند."]]','cambridge',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
