INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:excavation','excavation','n','حفاری','≈ digging, unearthing — Cambridge 10 · Test 4 · Passage 2: The Lost Civilisations of South America | Cambridge 11 · Test 2 · Passage 1: Irrigation in Ancient Civilisations | Cambridge 12 · Test 4 · Passage 3: Dinosaur Extinction & Fossil Study','Excavations uncovered the remains of an ancient city.','[["Excavations uncovered the remains of an ancient city.","کاوش‌ها بقایای یک شهر باستانی را کشف کردند."],["Excavations revealed ancient water channels.","حفاری‌ها کانال‌های آب باستانی را نشان دادند."],["Excavations uncovered a nearly complete dinosaur skeleton.","حفاری‌ها یک اسکلت تقریبا کامل دایناسور را کشف کردند."],["Excavations unearthed well-preserved rock art.","در حفاری‌ها، هنر صخره‌ای به خوبی حفظ شده کشف شد."]]','cambridge',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
