INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:linguistic','linguistic','adj','زبانی','≈ language-related, verbal — Cambridge 10 · Test 4 · Passage 3: The Globalization of English | Cambridge 14 · Test 2 · Passage 3: Intelligence & Learning Theories','Linguistic diversity is declining worldwide.','[["Linguistic diversity is declining worldwide.","تنوع زبانی در سراسر جهان رو به کاهش است."],["Linguistic intelligence supports writing and communication.","هوش زبانی از نوشتن و ارتباط پشتیبانی می‌کند."]]','cambridge',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
