INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:multilingual','multilingual','adj','چندزبانه','≈ polyglot, bilingual — Cambridge 10 · Test 4 · Passage 3: The Globalization of English','Multilingual speakers have cognitive advantages.','[["Multilingual speakers have cognitive advantages.","سخنرانان چند زبانه دارای مزایای شناختی هستند."]]','cambridge',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:dominance','dominance','n','برتری، تسلط','≈ control, authority — Cambridge 10 · Test 4 · Passage 3: The Globalization of English | Cambridge 12 · Test 2 · Passage 3: Global English | Cambridge 14 · Test 3 · Passage 3: Human Cooperation and Evolution','The dominance of English affects local cultures.','[["The dominance of English affects local cultures.","تسلط انگلیسی بر فرهنگ‌های محلی تأثیر می‌گذارد."],["The dominance of English impacts local languages.","تسلط انگلیسی بر زبان‌های محلی تأثیر می‌گذارد."],["Dominance behavior appears in both humans and animals.","رفتار سلطه گری هم در انسان و هم در حیوانات ظاهر می‌شود."]]','cambridge',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:assimilation','assimilation','n','جذب فرهنگی یا زبانی','≈ integration, absorption — Cambridge 10 · Test 4 · Passage 3: The Globalization of English | Cambridge 15 · Test 4 · Passage 3: Human Migration & Global Demographics','Language assimilation reduces minority identities.','[["Language assimilation reduces minority identities.","یکسان سازی زبان هویت‌های اقلیت‌ها را کاهش می‌دهد."],["Assimilation takes generations to complete.","یکسان سازی نسل‌ها طول می‌کشد تا کامل شود."]]','cambridge',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:dialect','dialect','n','گویش','≈ regional language, vernacular — Cambridge 10 · Test 4 · Passage 3: The Globalization of English | Cambridge 12 · Test 2 · Passage 3: Global English','Each region has its own dialect.','[["Each region has its own dialect.","هر منطقه گویش مخصوص به خود را دارد."],["Dialects enrich cultural diversity.","گویش‌ها تنوع فرهنگی را غنی می‌کنند."]]','cambridge',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:acculturation','acculturation','n','سازگاری فرهنگی','≈ adaptation, cultural exchange — Cambridge 10 · Test 4 · Passage 3: The Globalization of English','Acculturation leads to hybrid languages.','[["Acculturation leads to hybrid languages.","فرهنگ پذیری به زبان‌های ترکیبی منجر می‌شود."]]','cambridge',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:homogenize','homogenize','v','یکنواخت کردن','≈ standardize, unify — Cambridge 10 · Test 4 · Passage 3: The Globalization of English','Global media homogenize linguistic expression.','[["Global media homogenize linguistic expression.","رسانه‌های جهانی بیان زبانی را یکسان می‌کنند."]]','cambridge',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:preserve','preserve','v','حفظ کردن','≈ protect, maintain — Cambridge 10 · Test 4 · Passage 3: The Globalization of English','Efforts are made to preserve endangered languages.','[["Efforts are made to preserve endangered languages.","تلاش‌ها برای حفظ زبان‌های در معرض خطر انجام می‌شود."]]','cambridge',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:extinction','extinction','n','انقراض، نابودی (زبان یا گونه)','≈ disappearance, eradication — Cambridge 10 · Test 4 · Passage 3: The Globalization of English | Cambridge 12 · Test 4 · Passage 3: Dinosaur Extinction & Fossil Study | Cambridge 13 · Test 2 · Passage 2: Polar Bears & Climate Change','Some indigenous languages face extinction.','[["Some indigenous languages face extinction.","برخی از زبان‌های بومی با انقراض روبرو هستند."],["The dinosaurs faced mass extinction 65 million years ago.","دایناسورها ۶۵ میلیون سال پیش با انقراض دسته جمعی روبرو شدند."],["The species faces possible extinction within decades.","این گونه در طی چند دهه با انقراض احتمالی روبرو می‌شود."],["Human activity accelerated species extinction.","فعالیت‌های انسانی انقراض گونه‌ها را تسریع کرد."]]','cambridge',2,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:hydroponic','hydroponic','adj','کشت بدون خاک','≈ soil-free, water-based — Cambridge 11 · Test 1 · Passage 1: Vertical Farming','Hydroponic farming saves water and space in urban areas.','[["Hydroponic farming saves water and space in urban areas.","کشاورزی هیدروپونیک باعث صرفه جویی در آب و فضا در مناطق شهری می‌شود."]]','cambridge',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:aeroponics','aeroponics','n','کشت در هوا (با مه مغذی)','≈ air cultivation — Cambridge 11 · Test 1 · Passage 1: Vertical Farming','Aeroponics allows plants to grow without soil or standing water.','[["Aeroponics allows plants to grow without soil or standing water.","آئروپونیک به گیاهان اجازه می‌دهد بدون خاک یا آب ایستاده رشد کنند."]]','cambridge',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:cultivation','cultivation','n','پرورش، کاشت','≈ growing, raising — Cambridge 11 · Test 1 · Passage 1: Vertical Farming','The vertical system supports the cultivation of fresh vegetables year-round.','[["The vertical system supports the cultivation of fresh vegetables year-round.","سیستم عمودی از کشت سبزیجات تازه در تمام طول سال پشتیبانی می‌کند."]]','cambridge',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:yield','yield','n','بازده / محصول دادن','n., v. · ≈ produce, output — Cambridge 11 · Test 1 · Passage 1: Vertical Farming','The farm''s yield doubled after automation.','[["The farm''s yield doubled after automation.","بازده مزرعه پس از اتوماسیون دو برابر شد."]]','cambridge',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:irrigation','irrigation','n','آبیاری','≈ watering, hydration — Cambridge 11 · Test 1 · Passage 1: Vertical Farming','Efficient irrigation prevents water loss in arid regions.','[["Efficient irrigation prevents water loss in arid regions.","آبیاری کارآمد از هدر رفتن آب در مناطق خشک جلوگیری می‌کند."]]','cambridge',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:harvest','harvest','v','برداشت محصول','v., n. · ≈ collect, gather — Cambridge 11 · Test 1 · Passage 1: Vertical Farming | Cambridge 13 · Test 2 · Passage 1: The Coconut Palm','The crops are harvested using automated robots.','[["The crops are harvested using automated robots.","محصولات با استفاده از روبات‌های خودکار برداشت می‌شوند."],["Farmers harvest coconuts by hand.","کشاورزان نارگیل را با دست برداشت می‌کنند."]]','cambridge',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:pesticide','pesticide','n','آفت‌کش','≈ insecticide, chemical spray — Cambridge 11 · Test 1 · Passage 1: Vertical Farming | Cambridge 15 · Test 2 · Passage 2: Bees and Agriculture','Indoor farms reduce the need for pesticides.','[["Indoor farms reduce the need for pesticides.","مزارع سرپوشیده نیاز به آفت کش‌ها را کاهش می‌دهند."],["Overuse of pesticides harms pollinators.","استفاده بیش از حد از آفت کش‌ها به گرده افشان‌ها آسیب می‌رساند."]]','cambridge',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:photosynthesis','photosynthesis','n','فتوسنتز','≈ light conversion — Cambridge 11 · Test 1 · Passage 1: Vertical Farming | Cambridge 12 · Test 3 · Passage 3: Marine Life & Deep Ocean Exploration | Cambridge 14 · Test 3 · Passage 2: Forest Ecosystems and Carbon Balance','LED lights enable photosynthesis in vertical farms.','[["LED lights enable photosynthesis in vertical farms.","چراغ‌های LED فتوسنتز را در مزارع عمودی امکان پذیر می‌کند."],["Some marine plants perform photosynthesis near the surface.","برخی از گیاهان دریایی فتوسنتز را در نزدیکی سطح انجام می‌دهند."],["Photosynthesis absorbs CO₂ and releases oxygen.","فتوسنتز CO2 را جذب کرده و اکسیژن آزاد می‌کند."]]','cambridge',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:artificial light','artificial light','n','نور مصنوعی','≈ man-made illumination — Cambridge 11 · Test 1 · Passage 1: Vertical Farming | Cambridge 16 · Test 3 · Passage 1: Architectural Lighting Design','Artificial light replaces sunlight in indoor farming.','[["Artificial light replaces sunlight in indoor farming.","نور مصنوعی جایگزین نور خورشید در کشاورزی داخلی می‌شود."],["Artificial light allows activity after sunset.","نور مصنوعی اجازه فعالیت بعد از غروب خورشید را می‌دهد."]]','cambridge',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:nutrient solution','nutrient solution','n','محلول مغذی','≈ fertilizer mixture — Cambridge 11 · Test 1 · Passage 1: Vertical Farming','The nutrient solution circulates through the system to feed plants.','[["The nutrient solution circulates through the system to feed plants.","محلول غذایی برای تغذیه گیاهان در سیستم گردش می‌کند."]]','cambridge',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:expedition','expedition','n','سفر اکتشافی','≈ journey, exploration — Cambridge 11 · Test 1 · Passage 2: Arctic Exploration | Cambridge 15 · Test 2 · Passage 3: The Exploration of the Arctic','The expedition aimed to reach the North Pole by sled.','[["The expedition aimed to reach the North Pole by sled.","هدف این اکسپدیشن رسیدن به قطب شمال با سورتمه بود."],["The expedition reached the Arctic in harsh conditions.","اکسپدیشن در شرایط سخت به قطب شمال رسید."]]','cambridge',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:navigator','navigator','n','ناوبر','≈ pathfinder, pilot — Cambridge 11 · Test 1 · Passage 2: Arctic Exploration','Early navigators relied on stars for direction.','[["Early navigators relied on stars for direction.","دریانوردان اولیه برای مسیریابی به ستاره‌ها متکی بودند."]]','cambridge',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:endurance','endurance','n','استقامت، پایداری','≈ stamina, perseverance — Cambridge 11 · Test 1 · Passage 2: Arctic Exploration | Cambridge 15 · Test 2 · Passage 3: The Exploration of the Arctic','The explorers showed great endurance in freezing conditions.','[["The explorers showed great endurance in freezing conditions.","کاشفان در شرایط یخبندان استقامت زیادی از خود نشان دادند."],["The explorers'' endurance was severely tested.","استقامت کاشفان به شدت مورد آزمایش قرار گرفت."]]','cambridge',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:perilous','perilous','adj','خطرناک','≈ hazardous, risky — Cambridge 11 · Test 1 · Passage 2: Arctic Exploration','Crossing the ice was a perilous challenge.','[["Crossing the ice was a perilous challenge.","عبور از یخ یک چالش خطرناک بود."]]','cambridge',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:provisions','provisions','n','آذوقه، تدارکات','≈ supplies, rations — Cambridge 11 · Test 1 · Passage 2: Arctic Exploration','The team ran out of provisions after two months.','[["The team ran out of provisions after two months.","این تیم پس از دو ماه تمام شد."]]','cambridge',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:latitude','latitude','n','عرض جغرافیایی','≈ geographic coordinate — Cambridge 11 · Test 1 · Passage 2: Arctic Exploration | Cambridge 12 · Test 3 · Passage 2: The History of Cartography | Cambridge 15 · Test 2 · Passage 3: The Exploration of the Arctic','They recorded their latitude each day at noon.','[["They recorded their latitude each day at noon.","آنها هر روز در ظهر عرض جغرافیایی خود را ثبت می‌کردند."],["Latitude is measured from the equator.","عرض جغرافیایی از خط استوا اندازه گیری می‌شود."],["The team recorded their latitude each day.","این تیم هر روز عرض جغرافیایی خود را ثبت می‌کرد."]]','cambridge',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
