INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:symmetry','symmetry','n','تقارن','≈ balance, proportion — Cambridge 11 · Test 3 · Passage 1: The Taj Mahal | Cambridge 12 · Test 1 · Passage 3: Neuroaesthetics | Cambridge 17 · Test 3 · Passage 2: Architecture & Emotional Experience','The garden''s design reflects perfect symmetry.','[["The garden''s design reflects perfect symmetry.","طراحی باغ نشان دهنده تقارن کامل است."],["Symmetry increases visual harmony.","تقارن هارمونی بصری را افزایش می‌دهد."],["Humans naturally prefer symmetry in design.","انسان‌ها به طور طبیعی تقارن را در طراحی ترجیح می‌دهند."]]','cambridge',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
