INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:assessment','assessment','n','ارزیابی، سنجش','≈ evaluation, appraisal — Cambridge 11 · Test 3 · Passage 3: Risk Perception | Cambridge 15 · Test 2 · Passage 1: Education Systems & Learning Models','Risk assessment helps guide public policy.','[["Risk assessment helps guide public policy.","ارزیابی ریسک به هدایت خط مشی عمومی کمک می‌کند."],["Continuous assessment improves learning outcomes.","ارزشیابی مستمر نتایج یادگیری را بهبود می‌بخشد."]]','cambridge',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:mitigation','mitigation','n','کاهش اثرات منفی','≈ reduction, alleviation — Cambridge 11 · Test 3 · Passage 3: Risk Perception | Cambridge 13 · Test 1 · Passage 2: Climate Change & Environmental Policy | Cambridge 15 · Test 4 · Passage 2: Urban Noise & Health Impacts','Effective mitigation reduces disaster impact.','[["Effective mitigation reduces disaster impact.","کاهش موثر اثرات بلایا را کاهش می‌دهد."],["Mitigation efforts aim to limit global warming.","تلاش‌های کاهشی با هدف محدود کردن گرمایش جهانی انجام می‌شود."],["Noise mitigation strategies include sound barriers.","راهبردهای کاهش نویز شامل موانع صوتی است."]]','cambridge',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
