INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:density','density','n','تراکم','≈ compactness, thickness — Cambridge 11 · Test 4 · Passage 2: The Great Fire of London | Cambridge 12 · Test 4 · Passage 1: Urban Development & City Design | Cambridge 13 · Test 3 · Passage 3: Glass Innovation','The fire spread rapidly due to high population density.','[["The fire spread rapidly due to high population density.","آتش به دلیل تراکم بالای جمعیت به سرعت گسترش یافت."],["High density increases demand for public transport.","تراکم بالا تقاضا برای حمل و نقل عمومی را افزایش می‌دهد."],["Glass density affects its refractive index.","چگالی شیشه بر ضریب شکست آن تأثیر می‌گذارد."]]','cambridge',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
