INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:reconstruction','reconstruction','n','بازسازی شهری','≈ rebuilding, redevelopment — Cambridge 11 · Test 4 · Passage 2: The Great Fire of London | Cambridge 15 · Test 1 · Passage 3: History of the Red Cross | Cambridge 15 · Test 4 · Passage 1: Cultural Heritage & Historical Conservation','Reconstruction plans reshaped London''s architecture.','[["Reconstruction plans reshaped London''s architecture.","طرح‌های بازسازی معماری لندن را تغییر داد."],["Reconstruction follows emergency relief efforts.","بازسازی به دنبال تلاش‌های امدادی اضطراری انجام می‌شود."],["Reconstruction follows archaeological documentation.","بازسازی به دنبال مستندات باستان شناسی است."]]','cambridge',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
