INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:short-term memory','short-term memory','n','حافظه کوتاه‌مدت','≈ working memory — Cambridge 11 · Test 4 · Passage 3: Memory & Forgetting | Cambridge 17 · Test 4 · Passage 1: Human Memory & Neuroscience','Short-term memory holds data for a few seconds.','[["Short-term memory holds data for a few seconds.","حافظه کوتاه مدت داده‌ها را برای چند ثانیه نگه می‌دارد."],["Short-term memory stores information briefly.","حافظه کوتاه مدت اطلاعات را به طور خلاصه ذخیره می‌کند."]]','cambridge',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:long-term memory','long-term memory','n','حافظه بلندمدت','≈ permanent storage — Cambridge 11 · Test 4 · Passage 3: Memory & Forgetting','Practice transfers facts into long-term memory.','[["Practice transfers facts into long-term memory.","تمرین حقایق را به حافظه بلند مدت منتقل می‌کند."]]','cambridge',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:amnesia','amnesia','n','فراموشی، از دست دادن حافظه','≈ memory loss — Cambridge 11 · Test 4 · Passage 3: Memory & Forgetting | Cambridge 17 · Test 4 · Passage 1: Human Memory & Neuroscience','The patient suffered amnesia after the accident.','[["The patient suffered amnesia after the accident.","بیمار پس از تصادف دچار فراموشی شد."],["Head injuries may cause temporary amnesia.","آسیب به سر ممکن است باعث فراموشی موقت شود."]]','cambridge',3,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
