INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:aesthetic','aesthetic','adj','هنری، زیباشناسانه','≈ artistic, decorative — Cambridge 12 · Test 1 · Passage 2: The Psychology of Collecting | Cambridge 13 · Test 1 · Passage 3: The Art of Photography | Cambridge 13 · Test 4 · Passage 2: Architectural Innovation & Design Philosophy','Aesthetic appeal motivates collectors.','[["Aesthetic appeal motivates collectors.","جذابیت زیبایی شناختی به مجموعه داران انگیزه می‌دهد."],["Aesthetic choices define artistic style.","انتخاب‌های زیبایی شناختی سبک هنری را تعریف می‌کند."],["Aesthetic design enhances the user''s experience.","طراحی زیبایی شناختی تجربه کاربر را افزایش می‌دهد."]]','cambridge',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
