INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:proto-language','proto-language','n','زبان اولیه انسان','≈ primitive language — Cambridge 12 · Test 2 · Passage 2: The Evolution of Language | Cambridge 17 · Test 2 · Passage 1: Origins of Human Language','Researchers trace modern languages to a single proto-language.','[["Researchers trace modern languages to a single proto-language.","محققان زبان‌های مدرن را به یک زبان اولیه واحد ردیابی می‌کنند."],["Linguists reconstruct ancient proto- languages.","زبان شناسان زبان‌های اولیه باستانی را بازسازی می‌کنند."]]','cambridge',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
