INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:paleoclimate','paleoclimate','n','اقلیم باستانی','≈ ancient climate — Cambridge 12 · Test 3 · Passage 1: Climate Change & The Earth''s History | Cambridge 15 · Test 3 · Passage 3: Climate Records & Historical Change (Geology & Environmental','Ice cores provide data about Earth''s paleoclimate.','[["Ice cores provide data about Earth''s paleoclimate.","هسته‌های یخ داده‌هایی را در مورد اقلیم دیرینه زمین ارائه می‌دهند."],["Paleoclimate studies rely on geological evidence.","مطالعات دیرینه اقلیم بر شواهد زمین شناسی تکیه دارد."]]','cambridge',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
