INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:interglacial','interglacial','adj','بین دوره‌ای یخچالی','≈ warm interval — Cambridge 12 · Test 3 · Passage 1: Climate Change & The Earth''s History','Interglacial eras allowed species to thrive.','[["Interglacial eras allowed species to thrive.","دوران بین یخبندان به گونه‌ها اجازه رشد داد."]]','cambridge',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:ice core','ice core','n','هسته یخ','≈ frozen sample — Cambridge 12 · Test 3 · Passage 1: Climate Change & The Earth''s History | Cambridge 15 · Test 3 · Passage 3: Climate Records & Historical Change (Geology & Environmental','Scientists analyse ice cores to study past temperatures.','[["Scientists analyse ice cores to study past temperatures.","دانشمندان برای بررسی دمای گذشته، هسته‌های یخ را تجزیه و تحلیل می‌کنند."],["Scientists analyze ice cores to study past climates.","دانشمندان هسته‌های یخ را برای مطالعه آب و هوای گذشته تجزیه و تحلیل می‌کنند."]]','cambridge',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
