INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:carbon dioxide','carbon dioxide','n','دی‌اکسید کربن','≈ CO₂ — Cambridge 12 · Test 3 · Passage 1: Climate Change & The Earth''s History','Carbon dioxide levels correlate with global temperature.','[["Carbon dioxide levels correlate with global temperature.","سطح دی اکسید کربن با دمای جهانی مرتبط است."]]','cambridge',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
