INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:erosion','erosion','n','فرسایش','≈ wearing away, degradation — Cambridge 12 · Test 3 · Passage 1: Climate Change & The Earth''s History | Cambridge 13 · Test 4 · Passage 1: Environmental Damage & Human Impact | Cambridge 15 · Test 4 · Passage 1: Cultural Heritage & Historical Conservation','Wind and water erosion shape Earth''s surface.','[["Wind and water erosion shape Earth''s surface.","فرسایش بادی و آبی سطح زمین را شکل می‌دهد."],["Water erosion removes fertile topsoil.","فرسایش آبی خاک سطحی حاصلخیز را از بین می‌برد."],["Erosion threatens many archaeological sites.","فرسایش بسیاری از مکان‌های باستانی را تهدید می‌کند."]]','cambridge',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:radiation','radiation','n','تابش، اشعه','≈ emission, rays — Cambridge 12 · Test 3 · Passage 1: Climate Change & The Earth''s History','Solar radiation influences global warming.','[["Solar radiation influences global warming.","تشعشعات خورشیدی بر گرم شدن زمین تأثیر می‌گذارد."]]','cambridge',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:fluctuation','fluctuation','n','نوسان','≈ variation, oscillation — Cambridge 12 · Test 3 · Passage 1: Climate Change & The Earth''s History | Cambridge 15 · Test 3 · Passage 3: Climate Records & Historical Change (Geology & Environmental','Temperature fluctuations are normal over millennia.','[["Temperature fluctuations are normal over millennia.","نوسانات دما طی هزاران سال طبیعی است."],["Climate fluctuations occurred in natural cycles.","نوسانات آب و هوا در چرخه‌های طبیعی رخ داده است."]]','cambridge',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
