INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:manuscript','manuscript','n','نسخه خطی','≈ handwritten document — Cambridge 12 · Test 3 · Passage 2: The History of Cartography','Early maps were preserved as illuminated manuscripts.','[["Early maps were preserved as illuminated manuscripts.","نقشه‌های اولیه به عنوان نسخه‌های خطی منور نگهداری می‌شدند."]]','cambridge',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:navigation','navigation','n','جهت‌یابی، ناوبری','≈ route planning — Cambridge 12 · Test 3 · Passage 2: The History of Cartography | Cambridge 13 · Test 3 · Passage 2: Arctic Tern Migration | Cambridge 15 · Test 2 · Passage 3: The Exploration of the Arctic','Accurate navigation depended on celestial observations.','[["Accurate navigation depended on celestial observations.","ناوبری دقیق به مشاهدات آسمانی بستگی داشت."],["Navigation is influenced by magnetic cues.","ناوبری تحت تأثیر نشانه‌های مغناطیسی است."],["Accurate navigation was vital for survival.","ناوبری دقیق برای بقا حیاتی بود."]]','cambridge',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:projection','projection','n','تصویر نقشه بر کره زمین','≈ representation, layout — Cambridge 12 · Test 3 · Passage 2: The History of Cartography | Cambridge 15 · Test 3 · Passage 3: Climate Records & Historical Change (Geology & Environmental','Map projection distorts size and distance.','[["Map projection distorts size and distance.","طرح ریزی نقشه اندازه و فاصله را تغییر می‌دهد."],["Climate projections guide environmental policies.","پیش بینی‌های اقلیمی سیاست‌های زیست محیطی را هدایت می‌کند."]]','cambridge',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:marine','marine','adj','دریایی','≈ oceanic, aquatic — Cambridge 12 · Test 3 · Passage 3: Marine Life & Deep Ocean Exploration','Marine ecosystems host diverse species.','[["Marine ecosystems host diverse species.","اکوسیستم‌های دریایی میزبان گونه‌های متنوعی هستند."]]','cambridge',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:abyssal','abyssal','adj','اعماق اقیانوس','≈ deep-sea, profound — Cambridge 12 · Test 3 · Passage 3: Marine Life & Deep Ocean Exploration','Abyssal zones receive no sunlight.','[["Abyssal zones receive no sunlight.","مناطق ابیسال هیچ نور خورشید را دریافت نمی‌کنند."]]','cambridge',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:submersible','submersible','n','زیردریایی کوچک','≈ underwater vehicle — Cambridge 12 · Test 3 · Passage 3: Marine Life & Deep Ocean Exploration | Cambridge 17 · Test 2 · Passage 2: Ocean Exploration & Technology','Scientists use submersibles to explore deep trenches.','[["Scientists use submersibles to explore deep trenches.","دانشمندان از شناورهای زیردریایی برای کاوش در گودال‌های عمیق استفاده می‌کنند."],["Submersibles collect deep- sea samples.","شناورها نمونه‌های اعماق دریا را جمع آوری می‌کنند."]]','cambridge',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
