INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:sonar','sonar','n','دستگاه مکان یابی صوتی زیر آب','≈ sound navigation — Cambridge 12 · Test 3 · Passage 3: Marine Life & Deep Ocean Exploration','Sonar detects underwater objects using sound waves.','[["Sonar detects underwater objects using sound waves.","سونار اجسام زیر آب را با استفاده از امواج صوتی تشخیص می‌دهد."]]','cambridge',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:specimen','specimen','n','نمونه زیستی','≈ sample, example — Cambridge 12 · Test 3 · Passage 3: Marine Life & Deep Ocean Exploration | Cambridge 12 · Test 4 · Passage 3: Dinosaur Extinction & Fossil Study | Cambridge 16 · Test 1 · Passage 1: Extinction of Megafauna','Scientists collected specimens from the ocean floor.','[["Scientists collected specimens from the ocean floor.","دانشمندان نمونه‌هایی را از کف اقیانوس جمع آوری کردند."],["The museum displayed a rare dinosaur specimen.","در این موزه یک دایناسور نادر به نمایش گذاشته شد."],["Fossil specimens were preserved in permafrost.","نمونه‌های فسیلی در پرمافراست حفظ شدند."]]','cambridge',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:metropolis','metropolis','n','کلان‌شهر','≈ large city, urban hub — Cambridge 12 · Test 4 · Passage 1: Urban Development & City Design','Tokyo is one of the world''s largest metropolises.','[["Tokyo is one of the world''s largest metropolises.","توکیو یکی از بزرگترین کلان شهرهای جهان است."]]','cambridge',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
