INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:redevelopment','redevelopment','n','بازسازی و نوسازی شهری','≈ urban renewal, reconstruction — Cambridge 12 · Test 4 · Passage 1: Urban Development & City Design | Cambridge 13 · Test 2 · Passage 3: Megacities & Urban Challenges','The old port area underwent major redevelopment.','[["The old port area underwent major redevelopment.","منطقه بندر قدیمی دستخوش بازسازی اساسی شد."],["Redevelopment projects modernize old neighborhoods.","پروژه‌های توسعه مجدد محله‌های قدیمی را مدرن می‌کند."]]','cambridge',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
