INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:pitch','pitch','n','زیر و بمی صدا','≈ tone, frequency — Cambridge 12 · Test 4 · Passage 2: The Psychology of Music | Cambridge 16 · Test 3 · Passage 3: Music Psychology & Brain Response','Perfect pitch allows recognition of any musical note.','[["Perfect pitch allows recognition of any musical note.","زیر و بمی عالی اجازه می‌دهد تا هر نت موسیقی را تشخیص دهید."],["Absolute pitch is rare among musicians.","صدای مطلق در میان نوازندگان نادر است."]]','cambridge',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
