INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:fossil','fossil','n','فسیل، سنگواره','≈ preserved remains — Cambridge 12 · Test 4 · Passage 3: Dinosaur Extinction & Fossil Study','Fossils provide evidence of ancient life.','[["Fossils provide evidence of ancient life.","فسیل‌ها شواهدی از زندگی باستانی ارائه می‌دهند."]]','cambridge',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:paleontologist','paleontologist','n','دیرینه‌شناس','≈ fossil scientist — Cambridge 12 · Test 4 · Passage 3: Dinosaur Extinction & Fossil Study | Cambridge 16 · Test 1 · Passage 1: Extinction of Megafauna','Paleontologists study the evolution of species.','[["Paleontologists study the evolution of species.","دیرینه شناسان تکامل گونه‌ها را مطالعه می‌کنند."],["Paleontologists study ancient ecosystems.","دیرینه شناسان اکوسیستم‌های باستانی را مطالعه می‌کنند."]]','cambridge',4,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
