INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('cambridge:insulation','insulation','n','عایق حرارتی','≈ protection, barrier — Cambridge 13 · Test 2 · Passage 2: Polar Bears & Climate Change | Cambridge 14 · Test 2 · Passage 1: Environmental Architecture | Cambridge 15 · Test 4 · Passage 2: Urban Noise & Health Impacts','Their thick fur provides insulation against cold.','[["Their thick fur provides insulation against cold.","خز ضخیم آنها در برابر سرما عایق است."],["Wall insulation improves energy efficiency.","عایق کاری دیوار باعث بهبود بهره وری انرژی می‌شود."],["Acoustic insulation lowers indoor noise levels.","عایق صوتی سطح سر و صدای داخلی را کاهش می‌دهد."]]','cambridge',5,1792272101460,1792272101460) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
